    rows.push(line('退居与宫外',people.filter(x=>x.admitted&&!x.active&&!x.dead&&!['已废','未入宫'].includes(x.status)).map(x=>`${esc136(x.title)} ${esc136(x.name)}（${esc136(x.status)}）`)));
