// Preserve the dynamic first extra-heir birth scene if an earlier compatibility rewrite dropped its text.
const firstExtraBirth148=(CHAPTERS||[]).flatMap(ch=>(ch.steps||[]).map(st=>({ch,st}))).find(x=>x.ch.title==='宫灯渐繁'&&String(x.st.heading||'').includes('玉牒又添一笔'))?.st;
if(firstExtraBirth148){
  firstExtraBirth148.text=s=>{
    const x=s?.flags?.extraHeirs?.[1];
    if(!x||x.skipped)return ['五月没有新的产报。尚宫局把预备的乳母牌收回柜里，皇后只叫太医院照旧请平安脉。'];
    const name=PEOPLE?.[x.mother]?.name||'生母';
    const rank=String(s?.ranks?.[x.mother]||'');
    const next={答应:'常在',常在:'贵人',贵人:'嫔'}[rank.match(/(答应|常在|贵人)$/)?.[1]||''];
    const mother=rank?`${name}（${rank}）`:name;
    return [
      `五月天刚亮，${mother}宫里传出婴啼。女医先报母体平安，过了一会儿才把孩子抱到灯下细看。`,
      `${mother}累得睁不开眼，仍撑着问了一句：“哭得响不响？”乳母说响，她才松开一直攥着的床单。`,
      `玉牒房午后来核名，纸上写着“${x.order||'皇嗣'}·${String(x.name||'').replace(/^杨/,'')}”。皇后看过乳母与夜值名单，叫人把孩子腕上的红绳松半指。`,
      next?`同日另下产育册旨，${mother}晋一级。传旨时她没起身，只在枕上谢恩，随后问孩子什么时候抱回来吃奶。`:`洗三与满月仍照常预备。太后另送来一床薄绫小被。`
    ];
  };
}

function literaryText148(chapter,step,paragraphs){
  const edits=LITERARY_EDITS_148.filter(x=>x.scene===(step?.heading||''));
  if(!edits.length)return paragraphs;
  return paragraphs.map(paragraph=>{
    let text=String(paragraph??'');
    for(const edit of edits)text=text.split(edit.from).join(edit.to);
    return text;
  });
}



