function restoredText151(chapter,step,paragraphs,s=state){
  let out=paragraphs.slice();
  for(const row of RESTORED_PROSE_151)if(chapter?.title===row.chapter&&String(step?.heading||'').includes(row.scene)){
    const value=row.text(s);out=row.append?[...out,...value]:value;
  }
  return out;
}

